#include <iostream>
#include <iomanip>
#include <cmath>

// Speed of light in vacuum (km/s)
constexpr double C_VACUUM = 299792.458;
constexpr double N_FIBER = 1.468; // Refractive index of standard silica glass
constexpr double N_AIR = 1.0003;  // Refractive index of terrestrial air

struct PropagationProfile {
    double distance_km;
    double velocity_km_s;
    double one_way_ms;
    double rtt_ms;
};

PropagationProfile calculate_profile(double distance_km, double refractive_index) {
    double v = C_VACUUM / refractive_index;
    double one_way = (distance_km / v) * 1000.0;
    return {distance_km, v, one_way, one_way * 2.0};
}

int main() {
    std::cout << "=== SPEED-OF-LIGHT PROPAGATION PHYSICS (CHICAGO -> NJ) ===\n";
    double geodesic_dist_km = 1175.0; // ~730 miles

    auto fiber = calculate_profile(geodesic_dist_km * 1.15, N_FIBER); // 15% fiber winding factor
    auto microwave = calculate_profile(geodesic_dist_km * 1.03, N_AIR); // 3% tower zig-zag factor

    std::cout << std::left << std::setw(15) << "Medium"
              << std::setw(15) << "Velocity (km/s)"
              << std::setw(15) << "One-Way (ms)"
              << "RTT (ms)\n";
    std::cout << "------------------------------------------------------------\n";
    std::cout << std::left << std::setw(15) << "Silica Fiber"
              << std::setw(15) << std::fixed << std::setprecision(1) << fiber.velocity_km_s
              << std::setw(15) << std::setprecision(3) << fiber.one_way_ms
              << fiber.rtt_ms << "\n";
    std::cout << std::left << std::setw(15) << "Air Microwave"
              << std::setw(15) << std::fixed << std::setprecision(1) << microwave.velocity_km_s
              << std::setw(15) << std::setprecision(3) << microwave.one_way_ms
              << microwave.rtt_ms << "\n";
    std::cout << "------------------------------------------------------------\n";
    std::cout << "Microwave Latency Advantage: " << (fiber.rtt_ms - microwave.rtt_ms) << " ms RTT Moat!\n";
    return 0;
}

#include <iostream>
#include <iomanip>
#include <vector>
