struct MicrowaveModemTelemetry {
    int tower_id;
    double received_power_dbm;
    double snr_db;
    double ber;
    bool carrier_lock;
};

void audit_tower_chain(const std::vector<MicrowaveModemTelemetry>& towers) {
    std::cout << "=== ATMOSPHERIC RAIN ATTENUATION & SNR AUDIT ===\n";
    std::cout << std::left << std::setw(10) << "Tower"
              << std::setw(15) << "Power (dBm)"
              << std::setw(12) << "SNR (dB)"
              << std::setw(15) << "BER"
              << "Link State\n";
    std::cout << "------------------------------------------------------------\n";
    for (const auto& t : towers) {
        std::string status = "OPTIMAL";
        if (t.snr_db < 15.0 || !t.carrier_lock) status = "CRITICAL [FADE]";
        else if (t.snr_db < 22.0) status = "WARNING [DEGRADED]";

        std::cout << std::left << "Hop " << std::setw(6) << t.tower_id
                  << std::setw(15) << std::fixed << std::setprecision(1) << t.received_power_dbm
                  << std::setw(12) << t.snr_db
                  << std::setw(15) << std::scientific << std::setprecision(1) << t.ber
                  << status << "\n";
    }
}

int main() {
    std::vector<MicrowaveModemTelemetry> chain = {
        {1, -38.5, 32.0, 1e-12, true},
        {2, -40.0, 30.5, 1e-11, true},
        {14, -68.2, 14.1, 8e-4, true}, // Severe squall line over Ohio
        {15, -74.5, 11.2, 4e-2, false} // Carrier drop
    };
    audit_tower_chain(chain);
    return 0;
}

#include <iostream>
#include <iomanip>
#include <string>
#include <cstdint>

enum class LinkState { GREEN_MICROWAVE, YELLOW_DUAL_STREAM, RED_FIBER };

class HybridFailoverRouter {
public:
    explicit HybridFailoverRouter(double yellow_snr_threshold, double red_snr_threshold)
        : yellow_snr_(yellow_snr_threshold), red_snr_(red_snr_threshold), state_(LinkState::GREEN_MICROWAVE) {}

    LinkState evaluate_state(double current_snr_db) {
        if (current_snr_db < red_snr_) {
            state_ = LinkState::RED_FIBER;
        } else if (current_snr_db < yellow_snr_) {
            state_ = LinkState::YELLOW_DUAL_STREAM;
        } else {
            state_ = LinkState::GREEN_MICROWAVE;
        }
        return state_;
    }

    void route_packet(uint64_t seq, const std::string& payload, double current_snr) {
        LinkState s = evaluate_state(current_snr);
        std::cout << "Seq " << seq << " | SNR: " << std::fixed << std::setprecision(1) << current_snr << " dB | ";
        if (s == LinkState::GREEN_MICROWAVE) {
            std::cout << "Routing [MICROWAVE ONLY] (4.1ms latency)\n";
        } else if (s == LinkState::YELLOW_DUAL_STREAM) {
            std::cout << "Routing [DUAL TRANSMIT: MW + FIBER] (Hitless Deduplication)\n";
        } else {
            std::cout << "Routing [FIBER ONLY] (6.8ms latency, Zero Drops)\n";
        }
    }

private:
    double yellow_snr_;
    double red_snr_;
    LinkState state_;
};

int main() {
    std::cout << "=== HYBRID MICROWAVE/FIBER FAILOVER ROUTER ===\n";
    HybridFailoverRouter router(24.0, 16.0);
    router.route_packet(101, "CME_BBO_UPDATE", 30.5);
    router.route_packet(102, "CME_BBO_UPDATE", 21.0);
    router.route_packet(103, "CME_BBO_UPDATE", 13.5);
    std::cout << "Sub-microsecond failover operational.\n";
    return 0;
}

